-- Longer search descriptions for the seeded blog posts. Only rows whose description is still the seeded one are changed,
-- so a description edited in the admin stays as the editor wrote it.
UPDATE `blog_posts` SET `seo_description`='איך בונים עיצוב לחולצות צבא עם סמל, משפט או תמונה, לצוות או למחזור, תוך שמירה על תהליך אישור מסודר ועל שימוש בחומרים מותרים.' WHERE `slug`='מדריך-הדפסה-על-חולצות-צבא' AND `seo_description`='איך לבנות עיצוב לחולצות צבא עם סמל, משפט או תמונה, תוך שמירה על תהליך אישור ועל שימוש בחומרים מותרים.';
UPDATE `blog_posts` SET `seo_description`='רעיונות לחולצות מעוצבות לימי הולדת: עיצוב אחד שמתאים לחוגג ולכל מי שמגיע לחגוג, איך בוחרים תמונות, ואיך אוספים מידות לכל המשפחה.' WHERE `slug`='הדפסה-על-חולצות-לימי-הולדת' AND `seo_description`='רעיונות לחולצה לימי הולדת ולחולצה מעוצבת לימי הולדת, עם עיצוב שמתאים לחוגג ולכל מי שמגיע לחגוג.';
UPDATE `blog_posts` SET `seo_description`='איך מתכננים חולצה ממותגת לעסק שמשלבת לוגו, צבעים ושפה אנושית, כך שהצוות באמת ירצה ללבוש אותה, ומה כדאי להכין לפני שפונים לסטודיו.' WHERE `slug`='הדפסת-לוגו-על-חולצות-לעסק' AND `seo_description`='איך לתכנן חולצה ממותגת או חולצה לעסק שמשלבת לוגו, צבעים ושפה אנושית שהצוות באמת ירצה ללבוש.';
UPDATE `blog_posts` SET `seo_description`='מדריך קצר לתכנון חולצות לאירועים: ימי הולדת, מסיבות, אירועי חברה וטיולים. איך בוחרים עיצוב, אוספים מידות ומתזמנים את המשלוח בלי לחץ.' WHERE `slug`='איך-להזמין-חולצות-לאירועים' AND `seo_description`='מדריך קצר לתכנון חולצות לאירועים, מימי הולדת ומסיבות ועד אירועי חברה, טיולים וכל רעיון חדש.';
UPDATE `blog_posts` SET `seo_description`='מדריך לבחירת תמונה, לכתיבת בריף קצר ולבניית הדפסה בעיצוב אישי שנראית טוב על חולצה אחת או על קבוצה שלמה, מהצילום ועד העיצוב שמאשרים.' WHERE `slug`='הדפסה-בעיצוב-אישי-מתמונה' AND `seo_description`='מדריך לבחירת תמונה, כתיבת בריף קצר ובניית הדפסה בעיצוב אישי שנראית טוב על חולצה אחת או על קבוצה.';
UPDATE `blog_posts` SET `seo_description`='מה כוללת הדפסה על חולצות בעיצוב אישי, איך מכינים קבצים ותמונות, מתי מאשרים את העיצוב לפני שמדפיסים, ואיך החולצות מגיעות עד הבית.' WHERE `slug`='מהי-הדפסה-על-חולצות' AND `seo_description`='מה כוללת הדפסה על חולצות בעיצוב אישי, איך מכינים קבצים ותמונות, ומתי מאשרים את העיצוב לפני שמדפיסים.';
UPDATE `blog_posts` SET `seo_description`='איזו תמונה מתאימה לחולצה בעיצוב אישי, כמה תמונות כדאי לשלוח, ומה לכתוב בבריף כדי לקבל כיוון עיצובי טוב יותר כבר בגרסה הראשונה.' WHERE `slug`='איך-לבחור-תמונה-לחולצה-בעיצוב-אישי' AND `seo_description`='איזו תמונה מתאימה לחולצה בעיצוב אישי, כמה תמונות לשלוח ומה כדאי לכתוב בבריף כדי לקבל כיוון טוב יותר.';
UPDATE `blog_posts` SET `seo_description`='רעיונות לחולצות לטיול משפחתי שמחברות בין היעד, המשפחה והבדיחות שילוו את הדרך. איך בוחרים רעיון אחד לכולם ואוספים מידות לילדים ולמבוגרים.' WHERE `slug`='חולצות-לטיול-משפחתי' AND `seo_description`='רעיונות לחולצות לטיול משפחתי שמחברות בין היעד, המשפחה והבדיחות שילוו את הדרך.';
UPDATE `blog_posts` SET `seo_description`='מדריך לתכנון מתנה לצוות לסוף שנה שמחברת בין הרגעים הגדולים, ההומור והאנשים שהובילו את השנה, עם עיצוב אישי על חולצה לכל חברי הצוות.' WHERE `slug`='מתנה-לצוות-לסוף-שנה' AND `seo_description`='מדריך לתכנון מתנה לצוות לסוף שנה שמחברת בין הרגעים הגדולים, ההומור והאנשים שהובילו את השנה.';
UPDATE `blog_posts` SET `seo_description`='איך מתכננים מתנות לעובדים לחג עם רעיון אנושי, איסוף מידות מסודר ועיצוב שמתאים לתרבות של הצוות, ומה כדאי לסגור מראש לפני ההזמנה.' WHERE `slug`='מתנות-לעובדים-לחג' AND `seo_description`='איך לתכנן מתנות לעובדים לחג עם רעיון אנושי, איסוף מידות מסודר ועיצוב שמתאים לתרבות של הצוות.';
UPDATE `blog_posts` SET `seo_description`='רעיונות לעיצוב חולצות משפחתיות לימי הולדת, לחופשות ולאירועים, עם מקום לכל מידה ולכל אופי. איך יוצרים מראה אחד שגם הילדים וגם המבוגרים אוהבים.' WHERE `slug`='חולצות-משפחתיות-בעיצוב-אישי' AND `seo_description`='רעיונות לעיצוב חולצות משפחתיות לימי הולדת, חופשות ואירועים, עם מקום לכל מידה ולכל אופי.';
UPDATE `blog_posts` SET `seo_description`='מדריך לבחירת מתנה לחברה הכי טובה: חולצה בעיצוב אישי עם תמונה, משפט פנימי וצבעים שמתאימים בדיוק לקשר ביניכן, ואיך הופכים בדיחה פרטית לעיצוב.' WHERE `slug`='מתנה-לחברה-הכי-טובה' AND `seo_description`='מדריך לבחירת מתנה לחברה הכי טובה עם תמונה, משפט פנימי וצבעים שמתאימים בדיוק לקשר ביניכן.';
UPDATE `blog_posts` SET `seo_description`='איך בוחרים מתנה לבת מצווה שמחברת בין תמונות, תחביבים, חברות ומשפחה לעיצוב צבעוני ומדויק על חולצה, ומה כדאי לאסוף לפני שפונים לסטודיו.' WHERE `slug`='מתנה-לבת-מצווה' AND `seo_description`='איך לבחור מתנה לבת מצווה שמחברת בין תמונות, תחביבים, חברות ומשפחה לעיצוב צבעוני ומדויק.';
UPDATE `blog_posts` SET `seo_description`='רעיונות למתנה מקורית ליום הולדת שמתחילה מתמונה, מתחביב או מבדיחה והופכת לעיצוב אישי שאפשר ללבוש. איך בונים הפתעה שיש מאחוריה סיפור.' WHERE `slug`='מתנה-מקורית-ליום-הולדת' AND `seo_description`='רעיונות למתנה מקורית ליום הולדת שמתחילה מתמונה, תחביב או בדיחה והופכת לעיצוב אישי שאפשר ללבוש.';
UPDATE `blog_posts` SET `seo_description`='מדריך לבחירת מתנות לגבר, מתנות לאישה ומתנות לאירוע לפי האדם, הקשר והסיטואציה, ואיך הופכים רעיון אישי לחולצה בעיצוב שמתאים באמת.' WHERE `slug`='מתנות-לגבר-ולאישה-לאירוע' AND `seo_description`='מדריך לבחירת מתנות לגבר, מתנות לאישה ומתנות לאירוע לפי האדם, הקשר והסיטואציה.';
UPDATE `blog_posts` SET `seo_description`='כל מה שצריך לדעת לפני שמזמינים חולצה לערב צוות: בחירת קונספט, איסוף מידות, צבעים ותזמון, ואיך מרכזים את כל הפרטים אצל איש קשר אחד.' WHERE `slug`='חולצה-לערב-צוות' AND `seo_description`='כל מה שצריך לדעת לפני שמזמינים חולצה לערב צוות, כולל קונספט, מידות, צבעים ותזמון.';
UPDATE `blog_posts` SET `seo_description`='רעיונות למתנה לערב צוות שאינה עוד חולצת לוגו, אלא עיצוב שמספר את הסיפור של האנשים. איך בונים חולצה שמחברת בין אנשים שונים בצוות אחד.' WHERE `slug`='מתנה-לערב-צוות' AND `seo_description`='רעיונות למתנה לערב צוות שאינה עוד חולצת לוגו, אלא עיצוב שמספר את הסיפור של האנשים.';
UPDATE `blog_posts` SET `seo_description`='איך בוחרים מתנה ליום הולדת של הבת שמכבדת את האישיות שלה ולא נשארת רק בתמונה אחת: עיצוב אישי צבעוני על חולצה, לפי מה שהיא באמת אוהבת.' WHERE `slug`='מתנה-ליום-הולדת-של-הבת' AND `seo_description`='איך לבחור מתנה ליום הולדת של הבת שמכבדת את האישיות שלה ולא נשארת רק בתמונה אחת.';
UPDATE `blog_posts` SET `seo_description`='מדריך לבניית מתנה ליום הולדת של הבן: חולצה בעיצוב אישי שמתאים לילד וגם לכל המשפחה, ורעיונות שהופכים את כולם לצוות אחד ביום החגיגה.' WHERE `slug`='מתנה-ליום-הולדת-של-הבן' AND `seo_description`='מדריך לבניית מתנה ליום הולדת של הבן, עם עיצוב שמתאים לילד וגם לכל המשפחה.';
UPDATE `blog_posts` SET `seo_description`='איך יוצרים קונספט אחיד, צבעוני ומחמיא לחולצות למסיבת רווקות, בלי להפוך את כולן לעוד קבוצה גנרית. רעיונות לחולצות שכל החברות ירצו ללבוש.' WHERE `slug`='מתנה-למסיבת-רווקות' AND `seo_description`='איך ליצור קונספט אחיד, צבעוני ומחמיא למסיבת רווקות בלי להפוך את כולן לעוד קבוצה גנרית.';
UPDATE `blog_posts` SET `seo_description`='מדריך לתכנון חולצה למסיבת רווקים, מבחירת הקונספט ועד התאמת המידות לכל החבורה, ואיך יוצרים עיצוב שכל החבר׳ה באמת ירצו ללבוש.' WHERE `slug`='מתנה-למסיבת-רווקים' AND `seo_description`='מדריך לתכנון חולצה למסיבת רווקים, מבחירת הקונספט ועד התאמת המידות לכל החבורה.';
UPDATE `blog_posts` SET `seo_description`='איך מוצאים מתנה לאבא שמבוססת על התחביבים, המשפטים וההרגלים שהופכים אותו לאבא שלכם, ורעיונות לחולצה אישית עם אופי שהוא באמת ילבש.' WHERE `slug`='מתנה-לאבא-בעיצוב-אישי' AND `seo_description`='איך למצוא מתנה לאבא שמבוססת על התחביבים, המשפטים וההרגלים שהופכים אותו לאבא שלכם.';
UPDATE `blog_posts` SET `seo_description`='רעיונות למתנה לאמא שמשלבת תמונות משפחתיות, הומור וזיכרון שאפשר ללבוש: חולצה בעיצוב אישי שלא נראית כמו עוד מתנה, ואיך בוחרים את הכיוון.' WHERE `slug`='מתנה-לאמא-בעיצוב-אישי' AND `seo_description`='רעיונות למתנה לאמא שמשלבת תמונות משפחתיות, הומור וזיכרון שאפשר ללבוש.';
UPDATE `blog_posts` SET `seo_description`='מדריך מעשי לבחירת תמונות, רעיון וסגנון למתנה בעיצוב אישי שמרגישה באמת שלכם, ואיך הופכים רעיון קטן לחולצה שכל המשפחה או החבורה לובשת.' WHERE `slug`='מתנה-בעיצוב-אישי' AND `seo_description`='מדריך מעשי לבחירת תמונות, רעיון וסגנון עבור מתנה בעיצוב אישי שמרגישה באמת שלכם.';
